function card(d,i=0){const r=record(d),saved=isSaved(d),onTrail=section==='schedule'&&view==='plan';return `<article data-category="${esc(d.category)}" class="card ${r.status==='claimed'?'done':''}"><div class="deal-heading"><span class="icon" aria-hidden="true">${icons[d.category]||'🎁'}</span><h3>${esc(d.business)}</h3></div><div class="offer">${esc(d.offer)}</div>${onTrail?`<p class="visit-date">${esc(labelDate(scheduleDate(d,0)))}</p>`:''}<div class="compact-card-actions"><button class="card-detail-button" data-details="${d.id}" aria-label="View treat from ${esc(d.business)}">View treat <span aria-hidden="true">↗</span></button>${r.status==='claimed'?'<span class="compact-status">✓ Claimed</span>':saved?(onTrail?`<button class="card-claim-button" data-claim="${d.id}">Mark claimed</button>`:'<span class="compact-status">✓ Saved</span>'):''}</div></article>`}
