function redemptionNotes(d){const match=d.notes?.match(/^(.*?) Purchase rule: (.*?)\. Window: (.*?)\. Research status:/);return match?`<p>${esc(match[1])}.</p><p><b>Purchase:</b> ${esc(match[2])}.<br><b>When:</b> ${esc(match[3])}.</p>`:`<p>${esc(d.notes)}</p>`}
